def avoid_count(n: int, alphabet: str, banned: list[str]) -> int:
    from collections import deque

    MOD = 1_000_000_007
    if n == 0:
        return 1
    if not banned:
        return pow(len(alphabet), n, MOD)

    char_index = {ch: i for i, ch in enumerate(alphabet)}
    width = len(alphabet)

    transitions = [[-1] * width]
    failure = [0]
    forbidden = [False]

    for word in banned:
        state = 0
        for ch in word:
            c = char_index[ch]
            if transitions[state][c] == -1:
                transitions[state][c] = len(transitions)
                transitions.append([-1] * width)
                failure.append(0)
                forbidden.append(False)
            state = transitions[state][c]
        forbidden[state] = True

    queue = deque()
    for c in range(width):
        child = transitions[0][c]
        if child == -1:
            transitions[0][c] = 0
        else:
            queue.append(child)

    while queue:
        state = queue.popleft()
        forbidden[state] |= forbidden[failure[state]]
        for c in range(width):
            child = transitions[state][c]
            if child == -1:
                transitions[state][c] = transitions[failure[state]][c]
            else:
                failure[child] = transitions[failure[state]][c]
                queue.append(child)

    safe_states = [s for s in range(len(transitions)) if not forbidden[s]]
    index = {state: i for i, state in enumerate(safe_states)}
    size = len(safe_states)

    matrix = [[0] * size for _ in range(size)]
    for i, state in enumerate(safe_states):
        for target in transitions[state]:
            if not forbidden[target]:
                matrix[i][index[target]] += 1

    def multiply(a, b):
        result = [[0] * size for _ in range(size)]
        for i, a_row in enumerate(a):
            result_row = result[i]
            for k, value in enumerate(a_row):
                if value:
                    b_row = b[k]
                    for j in range(size):
                        result_row[j] += value * b_row[j]
            for j in range(size):
                result_row[j] %= MOD
        return result

    counts = [0] * size
    counts[index[0]] = 1

    while n:
        if n & 1:
            next_counts = [0] * size
            for i, value in enumerate(counts):
                if value:
                    row = matrix[i]
                    for j in range(size):
                        next_counts[j] += value * row[j]
            counts = [value % MOD for value in next_counts]

        n >>= 1
        if n:
            matrix = multiply(matrix, matrix)

    return sum(counts) % MOD
